            'PermG_fwd': m.get('PermG_fwd'),
            'PermG_rev': m.get('PermG_rev'),
            'hypothesis': val.get('hypothesis', '')[:80]
        }
# Sort by key
for k in sorted(nearby.keys()):
    print(f'{k}: PermG_fwd={nearby[k][\"PermG_fwd\"]}, PermG_rev={nearby[k][\"PermG_rev\"]}')
